  1	import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
  2	import type {SessionCursor} from '../../types/sessionStore.js';
  3	
  4	const MAX_CONTENT_LENGTH = 10000;
  5	const MAX_SESSION_ID_LENGTH = 128;
  6	
  7	interface ValidationSuccess {
  8	  valid: true;
  9	  data: IncomingMessage;
 10	}
 11	
 12	interface ValidationFailure {
 13	  valid: false;
 14	  error: string;
 15	}
 16	
 17	export type ValidationResult = ValidationSuccess | ValidationFailure;
 18	
 19	export function validateMessage(payload: unknown): ValidationResult {
 20	  if (typeof payload !== 'object' || payload === null) {
 21	    return {valid: false, error: 'Message must be an object'};
 22	  }
 23	
 24	  const message = payload as Record<string, unknown>;
 25	
 26	  if (typeof message.type !== 'string') {
 27	    return {valid: false, error: 'Message must have a type field'};
 28	  }
 29	
 30	  switch (message.type) {
 31	    case 'user_message':
 32	      return validateUserMessage(message);
 33	    case 'ping':
 34	      return validatePingMessage(message);
 35	    case 'list_sessions':
 36	      return validateListSessionsMessage(message);
 37	    default:
 38	      return {valid: false, error: `Unknown message type: ${message.type}`};
 39	  }
 40	}
 41	
 42	function validateUserMessage(message: Record<string, unknown>): ValidationResult {
 43	  if (typeof message.content !== 'string') {
 44	    return {valid: false, error: 'user_message must have content string'};
 45	  }
 46	
 47	  const trimmed = message.content.trim();
 48	
 49	  if (trimmed.length === 0) {
 50	    return {valid: false, error: 'Message content cannot be empty'};
 51	  }
 52	
 53	  if (message.content.length > MAX_CONTENT_LENGTH) {
 54	    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
 55	  }
 56	
 57	  return {
 58	    valid: true,
 59	    data: {
 60	      type: 'user_message',
 61	      content: message.content,
 62	    },
 63	  };
 64	}
 65	
 66	function validatePingMessage(message: Record<string, unknown>): ValidationResult {
 67	  if (typeof message.timestamp !== 'number') {
 68	    return {valid: false, error: 'ping must have timestamp number'};
 69	  }
 70	
 71	  return {
 72	    valid: true,
 73	    data: {
 74	      type: 'ping',
 75	      timestamp: message.timestamp,
 76	    },
 77	  };
 78	}
 79	
 80	function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
 81	  const data: ListSessionsMessage = {type: 'list_sessions'};
 82	
 83	  if (message.limit !== undefined) {
 84	    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
 85	      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
 86	    }
 87	    data.limit = message.limit;
 88	  }
 89	
 90	  if (message.before !== undefined) {
 91	    const before = validateCursor(message.before);
 92	    if (typeof before === 'string') return {valid: false, error: before};
 93	    data.before = before;
 94	  }
 95	
 96	  return {valid: true, data};
 97	}
 98	
 99	/** The cursor a client sends back from a row it was given, or the reason it cannot page from it. */
100	function validateCursor(value: unknown): SessionCursor | string {
101	  if (typeof value !== 'object' || value === null) return 'list_sessions before must be an object';
102	  const {sessionId, updatedAt} = value as Record<string, unknown>;
103	  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH) {
104	    return `list_sessions before.sessionId must be 1-${MAX_SESSION_ID_LENGTH} characters`;
105	  }
106	  if (
107	    (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') ||
108	    !Number.isFinite(new Date(updatedAt).getTime())
109	  ) {
110	    return 'list_sessions before.updatedAt must be a date string or number';
111	  }
112	  return {updatedAt, sessionId};
113	}
  1	import {WebSocket} from 'ws';
  2	import type {SessionEntry} from '../../types/session.js';
  3	import type {ChatSession} from '../../types/session.js';
  4	import {ErrorCodes} from '../../types/messages.js';
  5	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
  6	import type {SessionStore} from '../../types/sessionStore.js';
  7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
  8	import {validateMessage} from './validation.js';
  9	import type {ValidationResult} from './validation.js';
 10	import {PerSessionLock} from '../../shared/perSessionLock.js';
 11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
 12	import {AIError} from '../../types/ai.js';
 13	import type {MessageChunk} from '../../types/ai.js';
 14	import {
 15	  createUserEntry,
 16	  createAssistantEntry,
 17	  createThinkingEntry,
 18	  createToolEntry,
 19	} from '../../orchestration/entryFactories.js';
 20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
 21	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
 22	import {log} from '../../shared/logger.js';
 23	
 24	interface StreamState {
 25	  thinkingIndex: number | null;
 26	  assistantIndex: number | null;
 27	  suppressOutput: boolean;
 28	  sentAssistantIndices: number[];
 29	}
 30	
 31	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
 32	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
 33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
 34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
 35	  const lock = new PerSessionLock();
 36	  return function handleMessage(
 37	    ws: WebSocket,
 38	    session: ChatSession,
 39	    rawMessage: unknown,
 40	    signal?: AbortSignal
 41	  ): Promise<void> {
 42	    const validation = validateMessage(rawMessage);
 43	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
 44	    if (isUserMessageFrame(rawMessage)) {
 45	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
 46	    }
 47	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
 48	    return wsErrorHandler(ws, () => answerFrame(ws, validation, session, sessionStore));
 49	  };
 50	}
 51	
 52	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
 53	async function answerInTurn(
 54	  ws: WebSocket,
 55	  session: ChatSession,
 56	  orchestrator: ChatOrchestrator,
 57	  validation: ValidationResult,
 58	  signal: AbortSignal | undefined
 59	): Promise<void> {
 60	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
 61	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
 62	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
 63	    return;
 64	  }
 65	  const startedAt = Date.now();
 66	  try {
 67	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
 68	  } finally {
 69	    endTurn(ws, session, signal, startedAt);
 70	  }
 71	}
 72	
 73	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
 74	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
 75	  if (signal?.aborted) {
 76	    log.info('message', 'turn abandoned: its socket closed', {
 77	      sessionId: session.sessionId,
 78	      elapsedMs: Date.now() - startedAt,
 79	    });
 80	    return;
 81	  }
 82	  sendStreamEnd(ws);
 83	}
 84	
 85	async function answerUserMessage(
 86	  ws: WebSocket,
 87	  session: ChatSession,
 88	  orchestrator: ChatOrchestrator,
 89	  validation: ValidationResult,
 90	  signal: AbortSignal | undefined
 91	): Promise<void> {
 92	  const message = validation.valid ? validation.data : undefined;
 93	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
 94	  return answerFrame(ws, validation, session);
 95	}
 96	
 97	async function answerFrame(
 98	  ws: WebSocket,
 99	  validation: ValidationResult,
100	  session: ChatSession,
101	  sessionStore?: SessionStore
102	): Promise<void> {
103	  if (!validation.valid) {
104	    log.warn('message', 'validation failed', {error: validation.error});
105	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
106	    return;
107	  }
108	
109	  const message = validation.data;
110	  if (message.type === 'ping') handlePing(ws, message.timestamp);
111	  if (message.type === 'list_sessions') await handleListSessions(ws, session, message, sessionStore);
112	}
113	
114	// The user is the connection's, never the frame's: the validator has already dropped any userId a client sent.
115	async function handleListSessions(
116	  ws: WebSocket,
117	  session: ChatSession,
118	  message: ListSessionsMessage,
119	  sessionStore: SessionStore | undefined
120	): Promise<void> {
121	  const summaries =
122	    (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
123	  const sessions = summaries.map(summary => ({
124	    sessionId: summary.sessionId,
125	    createdAt: summary.createdAt.toISOString(),
126	    updatedAt: summary.updatedAt.toISOString(),
127	    entryCount: summary.entryCount,
128	  }));
129	  sendJson(ws, {type: 'session_list', sessions});
130	}
131	
132	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
133	function isUserMessageFrame(rawMessage: unknown): boolean {
134	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
135	}
136	
137	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
138	  try {
139	    await action();
140	  } catch (error) {
141	    const message = error instanceof Error ? error.message : 'Unknown error';
142	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
143	    log.error('message', 'handling error', {error: message, code});
144	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
145	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
146	      return;
147	    }
148	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
149	  }
150	}
151	
152	async function handleUserMessage(
153	  ws: WebSocket,
154	  session: ChatSession,
155	  orchestrator: ChatOrchestrator,
156	  content: string,
157	  signal: AbortSignal | undefined
158	): Promise<void> {
159	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
160	
161	  const userEntry = createUserEntry(content);
162	  const userIndex = appendEntry(session, userEntry);
163	  sendUpsert(ws, userIndex, userEntry);
164	
165	  const parser = new ThinkingTagParser();
166	  const state: StreamState = {
167	    thinkingIndex: null,
168	    assistantIndex: null,
169	    suppressOutput: false,
170	    sentAssistantIndices: [],
171	  };
172	
173	  let textChunkCount = 0;
174	
175	  try {
176	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
177	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
178	      if (signal?.aborted) break;
179	      textChunkCount = logChunk(chunk, textChunkCount);
180	      processChunk(ws, session, state, parser, chunk);
181	    }
182	  } finally {
183	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
184	    flushHeldText(ws, session, state, parser);
185	    closeCutOff(ws, session, state, 'thinkingIndex');
186	    closeCutOff(ws, session, state, 'assistantIndex');
187	  }
188	
189	  if (textChunkCount > 0) {
190	    log.debug('stream', `received ${textChunkCount} text chunks`);
191	  }
192	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
193	}
194	
195	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
196	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
197	  if (chunk.type === 'text') return textChunkCount + 1;
198	
199	  if (textChunkCount > 0) {
200	    log.debug('stream', `received ${textChunkCount} text chunks`);
201	  }
202	
203	  if (chunk.type === 'tool_result') {
204	    log.debug('stream', 'tool_result chunk', {
205	      messageCount: chunk.clientMessages.length,
206	      types: chunk.clientMessages.map(m => m.type),
207	    });
208	    return 0;
209	  }
210	
211	  log.debug('stream', 'chunk', {type: chunk.type});
212	  return 0;
213	}
214	
215	function processChunk(
216	  ws: WebSocket,
217	  session: ChatSession,
218	  state: StreamState,
219	  parser: ThinkingTagParser,
220	  chunk: MessageChunk
221	): void {
222	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
223	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
224	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
225	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
226	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
227	}
228	
229	function processTextChunk(
230	  ws: WebSocket,
231	  session: ChatSession,
232	  state: StreamState,
233	  parser: ThinkingTagParser,
234	  text: string
235	): void {
236	  const segments = parser.push(text);
237	  for (const segment of segments) {
238	    handleTextSegment(ws, session, state, segment);
239	  }
240	}
241	
242	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
243	  if (segment.type === 'thinking') {
244	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
245	    return;
246	  }
247	  commitAndClear(ws, session, state, 'thinkingIndex');
248	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
249	}
250	
251	function streamSegment(
252	  ws: WebSocket,
253	  session: ChatSession,
254	  state: StreamState,
255	  key: StateIndexKey,
256	  createEntry: EntryFactory,
257	  content: string
258	): void {
259	  const isNew = initSegment(session, state, key, createEntry);
260	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
261	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
262	  appendDelta(session, state[key]!, content);
263	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
264	}
265	
266	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
267	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
268	  markSuppressed(session, index);
269	  sendSkip(ws, index);
270	}
271	
272	function markSuppressed(session: ChatSession, index: number): void {
273	  const entry = session.entries[index];
274	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
275	}
276	
277	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
278	  if (state[key] !== null) return false;
279	  state[key] = appendEntry(session, createEntry());
280	  return true;
281	}
282	
283	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
284	  const index = state[key];
285	  if (index === null) return;
286	
287	  commitEntry(session, index);
288	  state[key] = null;
289	
290	  // Only what the client received can be retracted, and only assistant entries.
291	  if (state.suppressOutput) return;
292	
293	  sendCommit(ws, index);
294	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
295	}
296	
297	function processToolUseChunk(
298	  ws: WebSocket,
299	  session: ChatSession,
300	  toolCall: {name: string; input: Record<string, unknown>}
301	): void {
302	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
303	  const toolIndex = appendEntry(session, toolEntry);
304	  sendUpsert(ws, toolIndex, toolEntry);
305	}
306	
307	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
308	  for (const msg of clientMessages) {
309	    log.debug('stream', 'forwarding client message to frontend', {
310	      type: msg.type,
311	      index: 'index' in msg ? msg.index : undefined,
312	    });
313	    sendJson(ws, msg);
314	  }
315	}
316	
317	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
318	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
319	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
320	  commitOpenEntries(ws, session, state);
321	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
322	
323	  for (const idx of state.sentAssistantIndices) {
324	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
325	    markSuppressed(session, idx);
326	  }
327	
328	  state.sentAssistantIndices = [];
329	  state.suppressOutput = true;
330	}
331	
332	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
333	  flushHeldText(ws, session, state, parser);
334	  commitOpenEntries(ws, session, state);
335	}
336	
337	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
338	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
339	  for (const segment of parser.flush()) {
340	    handleTextSegment(ws, session, state, segment);
341	  }
342	}
343	
344	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
345	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
346	  const index = state[key];
347	  if (index === null) return;
348	  markTruncated(session, index);
349	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
350	  commitAndClear(ws, session, state, key);
351	}
352	
353	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
354	  commitAndClear(ws, session, state, 'thinkingIndex');
355	  commitAndClear(ws, session, state, 'assistantIndex');
356	}
357	
358	function handlePing(ws: WebSocket, timestamp: number): void {
359	  ws.send(JSON.stringify({type: 'pong', timestamp}));
360	}

